import{_ as t,o as a,c as o,a3 as s}from"./chunks/framework.Ki30n65y.js";const u=JSON.parse('{"title":"Operate and upgrade","description":"","frontmatter":{},"headers":[],"relativePath":"install/operations.md","filePath":"install/operations.md"}'),d={name:"install/operations.md"};function i(n,e,r,h,c,l){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="operate-and-upgrade" tabindex="-1">Operate and upgrade <a class="header-anchor" href="#operate-and-upgrade" aria-label="Permalink to &quot;Operate and upgrade&quot;">​</a></h1><p>Day-to-day tasks for a DepGate installation made with <a href="./docker">Install with Docker</a> or <a href="./kubernetes">Install on Kubernetes</a>. Compose commands run from the setup folder (<code>deploy/all-in-one/</code> or <code>deploy/app-only/</code>); Kubernetes commands have their own section on that page.</p><h2 id="everyday-commands" tabindex="-1">Everyday commands <a class="header-anchor" href="#everyday-commands" aria-label="Permalink to &quot;Everyday commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Task</th><th>Command</th></tr></thead><tbody><tr><td>Start, or apply changes to <code>.env</code></td><td><code>./3-run.sh</code> (or <code>docker compose up -d</code>)</td></tr><tr><td>Stop (data is kept)</td><td><code>./3-run.sh --stop</code></td></tr><tr><td>Follow the logs</td><td><code>./3-run.sh --logs</code></td></tr><tr><td>Status</td><td><code>docker compose ps</code></td></tr><tr><td>Reload the TLS certificate now</td><td><code>docker compose kill -s HUP app</code></td></tr></tbody></table><h2 id="health-checks" tabindex="-1">Health checks <a class="header-anchor" href="#health-checks" aria-label="Permalink to &quot;Health checks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Returns</th><th>Use for</th></tr></thead><tbody><tr><td><code>/healthz</code></td><td><code>{&quot;status&quot;:&quot;ok&quot;}</code> while the process runs</td><td>Liveness</td></tr><tr><td><code>/readyz</code></td><td><code>{&quot;status&quot;:&quot;ready&quot;}</code> when PostgreSQL and Redis are reachable, plus the Redis eviction policy</td><td>Readiness, load balancer health</td></tr></tbody></table><p>Both are available on the public address. With <code>MANAGEMENT_PORT</code> set (port 9464 in every production setup), they are also served on that private port, where the container health check and the Kubernetes probes read them.</p><p>On a managed Redis that blocks <code>CONFIG</code> (Memorystore, ElastiCache), DepGate cannot read the eviction policy and <code>/readyz</code> reports it as <code>unknown</code>. Verify <code>noeviction</code> in the service&#39;s console.</p><h2 id="metrics" tabindex="-1">Metrics <a class="header-anchor" href="#metrics" aria-label="Permalink to &quot;Metrics&quot;">​</a></h2><p>DepGate exposes Prometheus metrics at <code>/metrics</code> on the management port (<code>http://app:9464/metrics</code> from a container on the Compose network). This port is never published. Useful metrics include:</p><table tabindex="0"><thead><tr><th>Metric</th><th>Watch for</th></tr></thead><tbody><tr><td><code>depgate_redis_memory_bytes{kind=&quot;used&quot;|&quot;max&quot;}</code></td><td>Alert when used memory passes 80 % of max.</td></tr><tr><td><code>depgate_jobs_failed_total</code></td><td>Webhook, email or scheduled jobs that failed.</td></tr><tr><td><code>depgate_ledger_rows_lost_total</code></td><td>Decision Ledger rows that could not be written (database unavailable).</td></tr><tr><td><code>depgate_stream_dropped_total</code></td><td>Events a log streaming destination did not receive, by reason.</td></tr></tbody></table><h2 id="background-jobs" tabindex="-1">Background jobs <a class="header-anchor" href="#background-jobs" aria-label="Permalink to &quot;Background jobs&quot;">​</a></h2><p>Webhook deliveries, email, monitoring rechecks and scheduled tasks run on job queues in Redis, shared by every replica. Their state is visible under <strong>Settings → Jobs</strong>, and every run under <strong>Jobs &amp; Feeds</strong>. See <a href="/depgate/admin/jobs">Jobs and data feeds</a>.</p><h2 id="retention" tabindex="-1">Retention <a class="header-anchor" href="#retention" aria-label="Permalink to &quot;Retention&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Data</th><th>Kept for</th><th>Setting</th></tr></thead><tbody><tr><td>Decision Ledger</td><td>180 days</td><td><code>LEDGER_RETENTION_DAYS</code></td></tr><tr><td>Audit Log</td><td>730 days</td><td><code>AUDIT_RETENTION_DAYS</code></td></tr><tr><td>Monitoring rows nobody downloaded</td><td>90 days</td><td><code>MONITOR_RETENTION_DAYS</code></td></tr><tr><td>Webhook deliveries</td><td>30 days</td><td><code>WEBHOOK_DELIVERY_RETENTION_DAYS</code></td></tr><tr><td>Job runs</td><td>90 days</td><td></td></tr></tbody></table><p><code>0</code> keeps the Decision Ledger, the Audit Log or the monitoring rows forever.</p><h2 id="back-up" tabindex="-1">Back up <a class="header-anchor" href="#back-up" aria-label="Permalink to &quot;Back up&quot;">​</a></h2><p>DepGate&#39;s state is in PostgreSQL. Back up the database regularly with your usual tooling. With the all-in-one setup, from <code>deploy/all-in-one/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pg_dump</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> depgate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Fc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> depgate</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> depgate-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%F</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.dump</span></span></code></pre></div><p>The custom format (<code>-Fc</code>) is what <code>pg_restore</code> reads. To restore, stop the app, run <code>pg_restore -U depgate -d depgate --clean --if-exists</code> inside the <code>postgres</code> container with the file on standard input, and start the app again (the all-in-one README has the exact commands).</p><p>Redis holds caches and job queues. It does not need a backup; on loss, caches refill from upstream.</p><p>Also keep a copy of <code>.env</code> (in particular <code>JWT_SECRET</code>, and in all-in-one the database passwords) and your certificate files. On Kubernetes, keep the <code>depgate-secrets</code> Secret.</p><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><p>DepGate upgrades its own database schema. Every release ships the whole chain of schema migrations; at startup the new version applies the ones the database is missing, in order, in one transaction, and then serves. The release you come from does not matter, and you can skip releases.</p><ol><li><p>Read the release notes for anything version-specific, and for any migration expected to take long.</p></li><li><p><strong>Stop every DepGate instance.</strong> Migrations run with the application stopped; rolling upgrades are not supported.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # all-in-one: the databases keep running</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./3-run.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stop</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # app only</span></span></code></pre></div><p>On Kubernetes, <code>strategy: Recreate</code> does this for you: every old pod stops before a new one starts.</p></li><li><p><strong>Back up the database</strong> (see <a href="#back-up">Back up</a>).</p></li><li><p>Set the new version and start it. The log shows the schema it found and the migrations it applies, then <code>Database schema at NNNN</code>.</p><ul><li>Compose: set <code>DEPGATE_VERSION</code> in <code>.env</code> (if you unpacked the new release&#39;s <code>deploy/</code> folder over the old one, <code>3-run.sh</code> warns when <code>.env</code> still names the old version), then <code>./3-run.sh</code>. It pulls the new image, or finds the one you loaded with <code>docker load</code>.</li><li>Kubernetes: set <code>newTag</code> in <code>kustomization.yaml</code>, then <code>kubectl apply -k deploy/kubernetes</code>.</li></ul></li><li><p>Check that the app is healthy (<code>docker compose ps</code> shows <code>(healthy)</code>; <code>kubectl -n depgate rollout status deployment/depgate</code>) and sign in.</p></li></ol><p><strong>If the upgrade fails</strong>, the database is unchanged: the log names the migration and the error and says so. Start the previous image again and report the log.</p><p><strong>To go back after a successful upgrade</strong>, stop DepGate, restore the backup, then start the previous image. Starting the previous image without restoring is refused: an older DepGate does not run against a newer schema.</p><div class="tip custom-block"><p class="custom-block-title">Several replicas</p><p>Instances that start together run their whole startup one at a time: one applies the migrations, creates the settings, the default repositories and (on an empty database) the first admin, while the others wait for it and then find everything done. The first install needs no special replica count. Still stop all of them before an upgrade, because an instance of the old version that keeps running can hold a lock on a table the upgrade changes. In that case the upgrade stops with &quot;A table is locked by another connection&quot; and nothing is changed.</p></div><h3 id="give-the-migration-time-to-finish" tabindex="-1">Give the migration time to finish <a class="header-anchor" href="#give-the-migration-time-to-finish" aria-label="Permalink to &quot;Give the migration time to finish&quot;">​</a></h3><p><code>/healthz</code> and <code>/readyz</code> only answer once the schema is up to date and the startup tasks are done. The Kubernetes manifests allow 10 minutes for this with a <code>startupProbe</code> (<code>periodSeconds: 10</code>, <code>failureThreshold: 60</code>); liveness is not checked until it passes. When the release notes announce a slow migration, raise <code>failureThreshold</code> before applying the new tag. A pod killed in the middle of a migration leaves the database unchanged (the transaction rolls back) and starts into the same wait again.</p><p>With Compose, Docker never stops or restarts a container for a failed health check, so nothing interrupts a long migration. <code>3-run.sh</code> waits the same 10 minutes and then reports with the log tail while the container keeps running.</p><h2 id="scale-out" tabindex="-1">Scale out <a class="header-anchor" href="#scale-out" aria-label="Permalink to &quot;Scale out&quot;">​</a></h2><p>DepGate replicas are stateless and share PostgreSQL and Redis. To run several:</p><ul><li>Put them behind a load balancer and set <code>DISABLE_SSL=true</code> with TLS on the load balancer. The Kubernetes manifests do this with 2 replicas; see <a href="./kubernetes">Install on Kubernetes</a>.</li><li>Use the same <code>JWT_SECRET</code> on every replica.</li><li>Give each replica its own disk for the artifact cache; it is never shared.</li><li>Every replica processes background jobs by default. Use <code>WORKERS</code> to dedicate replicas to jobs (<code>all</code>, <code>none</code>, or a list such as <code>webhooks,email</code>).</li><li>Scheduled tasks run once per interval for the whole cluster, whatever the number of replicas.</li></ul><h2 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs&quot;">​</a></h2><p>DepGate writes structured JSON logs to standard output. Set <code>LOG_LEVEL</code> to <code>debug</code>, <code>info</code> (default), <code>warn</code> or <code>error</code>. Each line includes the request ID, so you can follow one request across the log.</p><p>To have DepGate&#39;s events (blocks, changes, sign-ins) in the same stream, add a <strong>Container output</strong> destination under <strong>Settings → Log streaming</strong>. See <a href="/depgate/admin/log-streaming">Log streaming</a>.</p>`,37)])])}const g=t(d,[["render",i]]);export{u as __pageData,g as default};
